var E={"pasta":"Ler-a-fundo","ficheiro":"Gramatica-Quem-Completa-Quem.html","id":"gram-complementos","cor":"#4f6f2a","corEscura":"#a3c47a","marca":"Gramática em contexto · M1 crónica","titulo":"Quem completa quem?","subtitulo":"Complemento do nome, do adjetivo e oblíquo na crónica de Fernão Lopes","niveis":["Reconhecer","Provar com um teste","Usar na tua escrita"],"emblemas":[[0.8,"Completo","Distingues o que uma palavra exige do que só a acompanha."],[0.5,"Bom caminho","Acertaste no essencial. Repete o teste: tira o constituinte e vê se a palavra fica a pedir alguma coisa."],[0,"A completar","Volta à pergunta: quem exige este complemento, um nome, um adjetivo ou um verbo?"]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Três frases da crónica","html":"<p>Três constituintes da <i>Crónica de D. João I</i>, cada um a completar uma palavra diferente:</p><p><b>A.</b> «fosse repartida a guarda <i>dos muros</i>» (cap. 115)</p><p><b>B.</b> «outras desacostumadas cousas pouco amigas <i>da natureza</i>» (cap. 148)</p><p><b>C.</b> «as pobres gentes não podiam chegar <i>a ele</i>» (cap. 148)</p><p class=\"nota\"><b>complemento</b> — o que uma palavra exige para o seu sentido ficar completo · <b>modificador</b> — o que se junta a uma palavra sem ser exigido</p>","links":[["Fernão Lopes, _Crónica de D. João I_, ed. 1897 (Internet Archive)","https://archive.org/details/chronicadeelreid0103lopeuoft"]]},{"nivel":1,"indice":1,"tipo":"unica","rot":"O nome exige","pergunta":"Em A, «dos muros» completa o nome «guarda». É um…","opcoes":[["complemento do nome","certo","Sim: «guarda» vem de _guardar_ e pede o que se guarda («a guarda» de quê?)."],["complemento do adjetivo","cuidado","Teste: «guarda» é nome, não adjetivo."],["complemento oblíquo","cuidado","Teste: o oblíquo completa um verbo; aqui completa um nome."]]},{"nivel":1,"tipo":"unica","rot":"O adjetivo exige","pergunta":"Em B, «da natureza» completa o adjetivo «amigas». É um…","opcoes":[["complemento do adjetivo","certo","Sim: «amigas» de quê? O adjetivo pede o complemento."],["complemento do nome","cuidado","Teste: a palavra completada é «amigas», adjetivo, e não «cousas»."],["modificador","cuidado","Teste: se tiro «da natureza», «pouco amigas» fica a pedir alguma coisa: é exigido."]]},{"nivel":2,"indice":3,"tipo":"multi","rot":"Pistas, não provas","pergunta":"Que testes ajudam a decidir? Toca nos que servem, mas repara no que não chega.","opcoes":[["Tirar o constituinte: a palavra fica a pedir alguma coisa?",5,"É o teste principal: exigido ou não."],["Ver que palavra é completada: nome, adjetivo ou verbo?",5,"Decide entre complemento do nome, do adjetivo e oblíquo."],["Perguntar à palavra completada «de quê?» ou «para onde?»",5,"Ajuda a ver o que a palavra pede: a guarda de quê, amigas de quê, correram para onde."],["Contar as palavras do constituinte",0,"O tamanho não diz nada sobre a função."]]},{"nivel":2,"tipo":"classificar","rot":"Quatro constituintes","pergunta":"Dá a função a cada constituinte sublinhado (frases feitas a partir da crónica).","categorias":["complemento do nome","complemento do adjetivo","complemento oblíquo","modificador"],"itens":[["a defesa <u>da cidade</u>",0],["as ruas estavam cheias <u>de gente</u>",1],["todos foram <u>aos paços</u>",2],["a casa <u>de pedra</u>",3]],"retorno":"«Defesa» pede; «cheias» pede; «foram» pede um lugar; «casa» não pede «de pedra»: é modificador."},{"nivel":3,"tipo":"unica","rot":"Título com adjetivo","pergunta":"Qual destes títulos sobre o cerco tem um complemento do adjetivo?","opcoes":[["Uma cidade cheia de medo guarda os muros","certo","«De medo» completa o adjetivo «cheia»: cheia de quê. É complemento do adjetivo."],["Uma cidade muito pobre guarda os muros","cuidado","«Muito» só intensifica «pobre»; o adjetivo não exige nada para ficar completo."],["Uma cidade cercada guarda os muros de noite","cuidado","«De noite» diz quando, junto ao verbo; «cercada» não pede complemento."]]}],"fontes":[["Fernão Lopes, _Crónica de D. João I_, caps. CXVI e CXLVIII, ed. 1897 (Internet Archive)","https://archive.org/details/chronicadeelreid0103lopeuoft"]],"imagemData":""};var PERCURSO="https://pedrohfernandes-klk.github.io/pt/m1/";
