var E={"pasta":"Ler-a-fundo","ficheiro":"Camoes-Aquela-Cativa.html","id":"camoes-barbara","cor":"#2f2f2f","corEscura":"#bdbdbd","marca":"Ler a fundo · M3 Camões","titulo":"«Aquela cativa»","subtitulo":"Luís de Camões, «Endechas a Bárbara escrava»","niveis":["Ler o que está lá","Ler nas entrelinhas","Fazer com o que leste"],"emblemas":[[0.8,"Leitor com olhos de hoje","Viste o elogio que desafia o gosto da época, e a voz que falta."],[0.5,"Bom começo","Já vês a inversão cativa/cativo. Repara em quem o poema contraria."],[0,"A entrar no poema","Relê: uma escrava que prende quem é livre."]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Ler","html":"<p><i>Aquela cativa,<br>Que me tem cativo,<br>Porque nela vivo,<br>Já não quer que viva.</i></p><p>[…]</p><p><i>Pretos os cabelos,<br>Onde o povo vão<br>Perde opinião,<br>Que os louros são belos.</i></p><p><i>Pretidão de Amor,<br>Tão doce a figura,<br>Que a neve lhe jura<br>Que trocara a cor.<br>Leda mansidão,<br>Que o siso acompanha,<br>Bem parece estranha,<br>Mas bárbara não.</i></p><p class=\"nota\"><b>o povo vão</b> — a gente comum, sem juízo · <b>perde opinião</b> — perde a convicção · <b>leda</b> — alegre · <b>siso</b> — juízo · <b>bárbara</b> — estrangeira, «selvagem» (jogo com o nome)</p>","links":[["_Obras Completas_, t. III (Project Gutenberg n.º 37192)","https://www.gutenberg.org/ebooks/37192"]]},{"nivel":1,"indice":1,"tipo":"unica","rot":"Cativa, cativo","pergunta":"«Aquela cativa, / Que me tem cativo»: que inversão há aqui?","opcoes":[["O homem livre comprou a escrava e prendeu-a","cuidado","O poema não fala de compra: fala de quem prende quem."],["A escrava prende o homem livre: a hierarquia vira-se","certo","Cativa (escrava) e cativo (preso por amor): a mesma palavra, dois sentidos."],["Os dois estão presos na mesma cadeia de amor","cuidado","Ela é cativa por condição; ele, por amor."]]},{"nivel":1,"indice":2,"tipo":"unica","rot":"Contra o gosto","pergunta":"«Pretos os cabelos, / Onde o povo vão / Perde opinião, / Que os louros são belos.» O que faz o poema ao gosto da época?","opcoes":[["Confirma-o: os cabelos louros continuam a ser os mais belos","cuidado","«Perde opinião»: diante dela, a gente comum perde essa convicção."],["Ignora-o: o poema não fala do que a gente comum acha belo","cuidado","Fala dele de propósito, «o povo vão», para o virar."],["Contraria-o: diante destes cabelos, o louro já não é o único belo","certo","A gente comum «perde opinião»: o gosto da época fica virado do avesso."]]},{"nivel":2,"tipo":"par","rot":"Cada verso, um gesto","pergunta":"Liga cada passagem ao que ela faz.","pares":[["Que a neve lhe jura / Que trocara a cor","a própria brancura preferia ser preta"],["Bem parece estranha, / Mas bárbara não","o nome e o preconceito: estrangeira sim, selvagem não"],["Que o siso acompanha","a doçura vem com juízo"],["Já não quer que viva","o amor que prende também mata"]],"retorno":"Elogio, jogo de palavras e recusa do preconceito, tudo em versos de cinco sílabas."},{"nivel":2,"tipo":"julgar","rot":"Com olhos de hoje","pergunta":"Quatro leituras de um colega. Quais têm prova no poema?","casos":[["O poema elogia uma beleza que a época não valorizava.",true,"Passa: «Pretidão de Amor», «Que os louros são belos» posto em causa."],["A mulher fala e diz o que sente.",false,"Não passa: nunca ouvimos a voz dela; o poema fala por ela."],["O poema recusa chamar-lhe «bárbara» no sentido de selvagem.",true,"Passa: «Mas bárbara não»."],["O poema questiona a escravatura.",false,"Não passa: ela continua «cativa»; o poema não discute a condição, só a beleza."]],"retorno":"Ler criticamente é ver as duas coisas: o que o poema desafia e o que deixa como está."},{"nivel":3,"tipo":"unica","rot":"A voz que falta","pergunta":"Qual destes pares de versos está mesmo na voz de Bárbara, a responder ao poeta?","opcoes":[["Aquela cativa, / que me tem cativo.","cuidado","É a voz do poeta, copiada do poema; Bárbara continua calada."],["Que linda que ela é, / de cabelos pretos e leda