var E={"pasta":"Ler-a-fundo","ficheiro":"Camoes-Restelo-Ramos.html","id":"camoes-restelo-ramos","cor":"#2f2f2f","corEscura":"#bdbdbd","marca":"Ler a fundo · _Os Lusíadas_","titulo":"E se ficasses na praia?","subtitulo":"Luís de Camões, _Os Lusíadas_, 1572, uma história com ramos","niveis":["Ler o que está lá","Escolher","Defender a escolha"],"emblemas":[[0.8,"Marinheiro do poema","Escolheste, atravessaste a tempestade ou ficaste em terra, e sabes o que Camões cantou e o que deixou na praia."],[0.5,"Meio caminho","Já percorreste um ramo. Recomeça e vê o que acontece a quem fica com o velho."],[0,"A entrar na praia","Relê a leitura: o velho fala, os batéis esperam, o poeta promete honras a quem arrisca."]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Ler","html":"<p><b>Luís de Camões</b>, o poeta deste módulo, conta em <i>Os Lusíadas</i> (1572) a viagem de Vasco da Gama à Índia. No canto IV, na praia do Restelo, um velho fala contra a partida e acaba assim:</p><p><i>Nenhum cometimento alto e nefando,<br>Por fogo, ferro, água, calma e frio,<br>Deixa intentado a humana geração.<br>Mísera sorte, estranha condição!</i></p><p>No canto VI, no meio da tempestade, o poeta diz o que ganham os que arriscam:</p><p><i>Por meio destes hórridos perigos,<br>Destes trabalhos graves e temores,<br>Alcançam os que são de fama amigos<br>As honras imortais e graus maiores</i></p><p class='nota'>A partir daqui, és um marinheiro da armada. No fim vês o que Camões escreveu.</p>"},{"nivel":2,"indice":1,"tipo":"ramos","rot":"A história com ramos","pergunta":"Em cada ponto, escolhe um caminho. Podes recomeçar e experimentar outro.","inicio":"a","nos":{"a":{"texto":"Frei Jorge pergunta: «Romeiro, romeiro! quem és tu?» O Romeiro está diante do retrato de D. João de Portugal. O que faz?","opcoes":[["Aponta o bordão para o retrato e diz «Ninguém»","b"],["Diz o nome em voz alta: «Sou D. João de Portugal»","c"],["Cala-se, aceita pão e parte sem dizer quem é","d"]]},"b":{"texto":"Frei Jorge fica a saber o que Madalena já tinha percebido ao ouvir o recado, quando fugiu a gritar: «Estou… estás… perdidas, desonradas… infames!» Se D. João está vivo, o casamento com Manuel não vale e Maria fica sem nome. Manuel de Sousa Coutinho tem de decidir.","opcoes":[["Manuel e Madalena tomam o hábito: morrem para o mundo","e"],["Manuel enfrenta o Romeiro e exige provas","f"]]},"c":{"texto":"Um nome dito em voz alta pode ser contestado. A casa divide-se: Telmo, o velho aio, reconhece-o; Madalena treme; Manuel quer provas. O Romeiro…","opcoes":[["Prova quem é com uma memória que só D. João podia ter","b"],["Recua: «enganei-me», e parte","d"]]},"d":{"fim":true,"texto":"O segredo fica com o Romeiro. Madalena continua casada, Maria continua filha legítima, e todos vivem sobre uma mentira que pode voltar um dia.","nota":"Garrett não escreveu este fim (caminho escrito para este exercício). Na peça, o Romeiro responde «Ninguém» e essa palavra desfaz a família inteira. Pergunta-te: que história é mais forte, a do segredo guardado ou a da palavra dita?"},"e":{"fim":true,"texto":"No ato III, Manuel chora a filha: «Desgraçada filha, que ficas órfã!… órfã de pai e mãe… e de família e de nome». Na capela, o Prior chama-lhe «irmão Luís de Sousa», porque «em tudo quisestes despir o homem velho». Maria, doente, entra: «aqui não morre ninguém sem mim», e morre.","nota":"É o fim de Garrett. A honra do fim do século XVI não deixa a Manuel outra saída, e a peça chama-se pelo nome novo dele: _Frei Luís de Sousa_."},"f":{"fim":true,"texto":"Manuel exige provas; Telmo e o retrato dão-nas. Fica tudo na mesma: D. João está vivo e o casamento não vale. Só se perdeu tempo.","nota":"Garrett não escreveu este fim (caminho escrito para este exercício). Na peça, ninguém pede provas: o retrato prova por si. Se Manuel lutasse, a peça seria um processo em tribunal, não uma tragédia."}}},{"nivel":2,"indice":2,"tipo":"unica","rot":"O que escreveu Camões","pergunta":"Qual é o caminho que está no poema?","opcoes":[["A armada ouve o velho e fica em terra, no Restelo","cuidado","O velho fala, mas a armada parte: o poema é a viagem."],["A armada parte apesar do velho e vence a tempestade","certo","Sim: «Alcançam os que são de fama amigos / As honras imortais e graus maiores»."],["A tempestade obriga a armada a voltar para trás","cuidado","A tempestade passa; o poeta usa-a para dizer o que custa a fama."]]},{"nivel":3,"tipo":"unica","rot":"Se partiste","pergunta":"Se o teu primeiro caminho foi o do poema, o que ganha a epopeia com a viagem?","opcoes":[["Uma vida segura na praia do Restelo, longe do fogo, do ferro e da água.","cuidado","Isso é o que o velho queria; a epopeia ganha com quem parte, não com quem fica."],["As «honras imortais e graus maiores» que só se alcançam por meio dos «hórridos perigos».","certo","É o que o poeta diz na tempestade: os que arriscam ganham honras e graus."],["A certeza de que a «humana geração» não deixa nada por tentar, nem o nefando.","cuidado","Isso é a queixa do velho, não o ganho da epopeia."]]},{"nivel":3,"tipo":"unica","rot":"Se ficaste","pergunta":"Se o teu primeiro caminho foi outro, o que tinha o velho de razão?","opcoes":[["Que a viagem traz «honras imortais e graus maiores» a quem é amigo da fama.","cuidado","Isso é o poeta na tempestade, a favor da partida; o velho diz o contrário."],["Que ninguém devia escrever epopeias, porque a poesia é uma «mísera sorte».","cuidado","A «mísera sorte» é a condição humana, não a poesia; o velho não fala de escrever."],["Que a «humana geração» não deixa nada por tentar, e paga caro por isso.","certo","É o aviso do velho: tentar tudo, mesmo o nefando, custa caro. Tinha razão nisso."]]}],"fontes":[["Luís de Camões, _Os Lusíadas_, texto integral (oslusiadas.org)","https://oslusiadas.org/"],["Os Lusíadas (Wikipédia)","https://pt.wikipedia.org/wiki/Os_Lus%C3%ADadas"]],"imagemData":""};var PERCURSO="https://pedrohfernandes-klk.github.io/pt/m3/";
