var E={"pasta":"Ler-a-fundo","ficheiro":"Gramatica-Dizer-e-Fazer.html","id":"gram-atos-fala","cor":"#2f4f6f","corEscura":"#9bbbd8","marca":"Gramática em contexto · M4 Vieira","titulo":"Dizer é fazer","subtitulo":"Atos de fala no _Sermão de Santo António_ e em _Frei Luís de Sousa_","niveis":["Reconhecer","Provar com um teste","Usar na tua escrita"],"emblemas":[[0.8,"Ouvido de pregador","Sabes o que cada frase faz a quem a ouve."],[0.5,"Bom caminho","Acertaste no essencial. Repete o teste: depois da frase, quem tem de fazer alguma coisa?"],[0,"A afinar","Volta à pergunta: a frase afirma, manda, promete ou desabafa?"]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Três frases de Vieira","html":"<p>Quem fala faz sempre alguma coisa a quem ouve.</p><p><b>A.</b> «Olhai, peixes, lá do mar para a terra.» (cap. IV)</p><p><b>B.</b> «os grandes comem os pequenos» (cap. IV)</p><p><b>C.</b> «Oh que boa doutrina era esta para a terra, se eu não pregara para o mar!» (cap. VI)</p><p class=\"nota\"><b>assertivo</b> — afirma alguma coisa como verdadeira · <b>diretivo</b> — leva o outro a agir · <b>compromissivo</b> — compromete quem fala · <b>expressivo</b> — exprime um estado de quem fala · <b>declarativo</b> — muda a realidade ao ser dito por quem pode</p>","links":[["Padre António Vieira, _Sermão de Santo António_ (Wikisource)","https://pt.wikisource.org/wiki/Serm%C3%A3o_de_Santo_Ant%C3%B3nio_(1654)"]]},{"nivel":2,"tipo":"multi","rot":"Pistas, não provas","pergunta":"Que perguntas ajudam a dar o nome ao ato? Toca nas que servem.","opcoes":[["Depois da frase, quem tem de fazer alguma coisa: quem ouve, quem fala, ninguém?",5,"Quem ouve, diretivo; quem fala, compromissivo."],["A frase pode ser verdadeira ou falsa?",5,"Se pode, é assertiva."],["Há uma interjeição ou uma exclamação que mostre o que sente quem fala?",5,"É a pista do expressivo."],["A frase é comprida?",0,"O tamanho não diz o que a frase faz."]]},{"nivel":2,"tipo":"classificar","rot":"Quatro atos","pergunta":"Diz o que faz cada frase.","categorias":["assertivo","diretivo","compromissivo","expressivo"],"itens":[["o dito polvo é o maior traidor do mar (Vieira, cap. V)",0],["Dizei-me, voadores, não vos fez Deus peixes? (Vieira, cap. V)",1],["Vivo ou morto, Madalena, hei de ver-vos pelo menos ainda uma vez neste mundo (Garrett, ato I)",2],["Ah peixes, quantas invejas vos tenho (Vieira, cap. VI)",3]],"retorno":"Afirmar, mandar responder, prometer, desabafar: quatro coisas que se fazem a falar."},{"nivel":3,"tipo":"unica","rot":"Três vezes","pergunta":"Pedir mais um dia de três maneiras: ordem, pergunta, afirmação. Qual destes conjuntos cumpre as três?","opcoes":[["«Dê-me mais um dia.» / «Podia dar-me mais um dia?» / «Preciso de mais um dia para o entregar.»","certo","Uma ordem no imperativo, uma pergunta, uma afirmação: três formas para o mesmo pedido."],["«Dê-me mais um dia.» / «Dê-me um dia, por favor.» / «Dê-me só até amanhã.»","cuidado","São três ordens: o «por favor» não muda a forma."],["«Podia dar-me mais um dia?» / «Será que dá para amanhã?» / «E se fosse na quinta?»","cuidado","São três perguntas; falta a ordem e falta a afirmação."]]},{"nivel":3,"tipo":"unica","rot":"Quem mais obriga","pergunta":"Das três, qual obriga mais quem ouve?","opcoes":[["«Podia dar-me mais um dia?»","cuidado","A pergunta deixa a porta aberta ao não."],["«Dê-me mais um dia.»","certo","É uma ordem: o imperativo não deixa escolha a quem ouve; é o ato diretivo mais forte."],["«Preciso de mais um dia para o entregar.»","cuidado","Afirma um estado de quem fala; quem ouve pode não fazer nada."]]},{"nivel":3,"tipo":"unica","rot":"A mais delicada","pergunta":"Qual é a mais delicada, e porquê?","opcoes":[["«Podia dar-me mais um dia?» Pergunta, no passado: deixa recusar sem ofensa.","certo","A pergunta e o «podia» dão a escolha a quem ouve; é a forma mais delicada de pedir."],["«Dê-me mais um dia.» É curta, logo é educada.","cuidado","Curta não é delicada: é uma ordem, e não deixa escolha."],["«Preciso de mais um dia.» Fala de mim, por isso não incomoda.","cuidado","Fala de quem pede, mas não pede: obriga o outro a adivinhar o pedido."]]}],"fontes":[["Padre António Vieira, _Sermão de Santo António_ (Wikisource)","https://pt.wikisource.org/wiki/Serm%C3%A3o_de_Santo_Ant%C3%B3nio_(1654)"],["Almeida Garrett, _Frei Luís de Sousa_ (Project Gutenberg n.º 17591)","https://www.gutenberg.org/ebooks/17591"]],"imagemData":""};var PERCURSO="https://pedrohfernandes-klk.github.io/pt/m4/";
