ov.addEventListener("click",function(e){if(e.target!==p)fecha()});document.body.appendChild(ov);document.documentElement.style.overflow="hidden";x.focus()}
function legendaDe(img){var f=img.closest("figure");if(f){var c=f.querySelector("figcaption");if(c)return c.textContent.replace(/\s+/g," ").trim()}return img.getAttribute("data-legenda")||img.alt||""}
function elegivel(img){if(!img||img.tagName!=="IMG")return false;if(img.closest("a,button,.amp-ov,.ver-fig,.lp-img,.mf,.cavalo"))return false;if(img.classList.contains("sem-amp"))return false;if(!img.closest("figure")&&!img.hasAttribute("data-ampliar"))return false;return true}
document.addEventListener("click",function(e){var img=e.target&&e.target.closest?e.target.closest("img"):null;if(!elegivel(img))return;e.preventDefault();abre(img,legendaDe(img))});
document.addEventListener("keydown",function(e){if(e.key==="Escape"&&ov){fecha();return}if((e.key==="Enter"||e.key===" ")&&elegivel(e.target)){e.preventDefault();abre(e.target,legendaDe(e.target))}});

