var E={"pasta":"Ler-a-fundo","ficheiro":"Tradutor-Detetive.html","id":"tradutor-detetive","cor":"#4a3b2a","corEscura":"#c9a97a","marca":"Ler a fundo · M4 Vieira e a Bíblia","titulo":"O tradutor-detetive","subtitulo":"Frederico Lourenço e o Pai Nosso","niveis":["Ler o que está lá","Ler nas entrelinhas","Fazer com o que leste"],"emblemas":[[0.8,"Palavra exata","Viste o que três palavras fazem a um texto que toda a gente sabe de cor."],[0.5,"Quase lá","Já apanhaste duas das três palavras. Volta a ler as duas versões lado a lado."],[0,"A comparar","Lê as duas versões em voz alta: a diferença ouve-se."]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Duas versões","html":"<p><b>Frederico Lourenço</b>, nascido em Lisboa em 1963, que ensina línguas clássicas em Coimbra e recebeu o Prémio Pessoa de 2016, traduz a Bíblia a partir do grego desde 2016. Em maio de 2026, numa sessão na Universidade de Coimbra, propôs esta versão do Pai Nosso (citada pela Agência Ecclesia):</p><p><i>Dá-nos hoje o nosso pão de amanhã; e perdoa as nossas dívidas, tal como nós já perdoámos aos nossos devedores.</i></p><p>Na missa, em português, diz-se «o pão nosso de cada dia», «perdoai-nos as nossas ofensas» e «não nos deixeis cair em tentação». Lourenço diz que, no grego de Mateus e de Lucas, não há «ofensas» nem «tentação»: há «dívidas» e «provação».</p>"},{"nivel":1,"tipo":"par","rot":"Palavra por palavra","pergunta":"Liga cada palavra da missa à palavra de Lourenço.","pares":[["ofensas","dívidas"],["tentação","provação"],["pão de cada dia","pão de amanhã"]]},{"nivel":1,"indice":2,"tipo":"unica","rot":"De onde vem","pergunta":"De que língua traduz Frederico Lourenço a Bíblia?","opcoes":[["Do latim","cuidado","O texto diz «a partir do grego»; o latim não entra."],["Do grego","certo","Sim: traduz «a partir do grego», o grego de Mateus e de Lucas."],["Do português antigo","cuidado","Não: parte do texto grego, não de uma versão portuguesa."]]},{"nivel":2,"indice":3,"tipo":"classificar","rot":"O que muda","pergunta":"Classifica cada efeito: vem da palavra «dívidas» ou da palavra «provação»?","categorias":["dívidas","provação"],"itens":[["Perdoar passa a ser deixar de cobrar o que se deve.",0],["O pedido deixa de ser «não me tentes» e passa a ser «não me ponhas à prova».",1],["A relação com Deus fica parecida com contas entre pessoas.",0],["O pedido fica mais perto de um exame do que de um convite ao mal.",1]],"retorno":"As dívidas trazem a linguagem do que se deve; a provação, a do teste."},{"nivel":2,"indice":4,"tipo":"unica","rot":"Perdoámos","pergunta":"Lourenço escreve «perdoámos», com acento. O que diz o acento?","opcoes":[["Que perdoamos ao mesmo tempo que pedimos","cuidado","Isso seria _perdoamos_, sem acento: presente."],["Que vamos perdoar um dia","cuidado","Não é futuro. O acento marca o passado."],["Que já perdoámos, antes de pedir perdão","certo","Sim: pretérito perfeito. A ordem dos gestos muda: primeiro perdoa-se, depois pede-se."]]},{"nivel":3,"tipo":"unica","rot":"Traduz tu","pergunta":"Mudar uma palavra para tornar a frase exata, como Lourenço com «dívidas». Qual destes pares faz isso?","opcoes":[["Antes: «Não se fala durante o teste.» Depois: «Não se conversa durante o teste.» Uma palavra, e ficou exato: pedir ajuda não é conversar.","certo","Uma palavra trocada muda o sentido: «conversar» diz o que «falar» dizia de mais."],["Antes: «Não se fala durante o teste.» Depois: «Durante a prova, cada um está em silêncio total e não pergunta nada.» Mudou tudo.","cuidado","Reescreveu a frase inteira; o desafio era mudar uma palavra."],["Antes: «Não se fala durante o teste.» Depois: «Não se fala durante o teste, está bem?» Acrescentou, não mudou.","cuidado","Acrescentar não torna exato; a palavra imprecisa ficou lá."]]},{"nivel":3,"tipo":"unica","rot":"A estranheza","pergunta":"Uma palavra nova num texto sabido de cor faz estranheza. Qual destas frases dá uma razão que se aguenta?","opcoes":[["Atrapalha, porque Lourenço não sabe grego e inventou as palavras.","cuidado","Lourenço traduz a partir do grego; a razão é falsa."],["Ajuda, porque obriga a ouvir o que se dizia sem pensar.","certo","A estranheza acorda a atenção: quem diz de cor volta a ouvir a palavra."],["Ajuda, porque o texto fica mais curto e decora-se melhor.","cuidado","Não fica mais curto; e decorar melhor não é perceber melhor."]]}],"fontes":[["Agência Ecclesia, «Frederico Lourenço sugere uma nova tradução da oração do Pai Nosso», 14 de maio de 2026","https://agencia.ecclesia.pt/portal/igreja-biblia-frederico-lourenco-sugere-uma-nova-traducao-da-oracao-do-pai-nosso/"],["Observador, «Frederico Lourenço vence Prémio Pessoa 2016», 9 de dezembro de 2016","https://observador.pt/2016/12/09/frederico-lourenco-vence-premio-pessoa-2016/"]],"imagemData":""};var PERCURSO="https://pedrohfernandes-klk.github.io/pt/m4/";
