var E={"pasta":"Ler-a-fundo","ficheiro":"Vieira-Nunca-Pior-Auditorio.html","id":"vieira-auditorio","cor":"#7a3b1e","corEscura":"#d29368","marca":"Ler a fundo · M4 Vieira","titulo":"Nunca pior auditório","subtitulo":"Padre António Vieira, 1654, caps. II–III","niveis":["Ler o que está lá","Ler nas entrelinhas","Fazer com o que leste"],"emblemas":[[0.8,"Leitor de ironias","Percebeste que o elogio aos peixes é uma crítica aos homens."],[0.5,"Bom começo","Já vês o elogio. Pergunta sempre: elogiar isto acusa quem?"],[0,"A entrar no sermão","Relê «ouvem e não falam» a pensar em quem fala e não ouve."]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Ler","html":"<p>Antes de repreender, Vieira louva os peixes. Começa assim:</p><p><i>«Enfim, que havemos de pregar hoje aos peixes? Nunca pior auditório. Ao menos têm os peixes duas boas qualidades de ouvintes: ouvem e não falam.»</i></p><p>E explica o que um pregador deve fazer, como o sal:</p><p><i>«Uma é louvar o bem, outra repreender o mal: louvar o bem para o conservar e repreender o mal para preservar dele.»</i></p><p class=\"nota\"><b>auditório</b> — público · <b>preservar dele</b> — proteger do mal</p>","links":[["Ler o sermão inteiro (Internet Archive)","https://archive.org/details/sermao-de-st-antonio-aos-peixes-lusolivros"]]},{"nivel":1,"tipo":"unica","rot":"Elogio ou crítica","pergunta":"«Ouvem e não falam.» É um elogio aos peixes ou uma crítica?","opcoes":[["As duas coisas: elogia os peixes para acusar os homens","certo","É ironia: o elogio mínimo aos peixes é uma seta apontada à plateia."],["Só um elogio: os peixes são bons ouvintes e calados","cuidado","Repara em «Nunca pior auditório»: o elogio vem com um encolher de ombros."],["Só uma crítica aos peixes, que são mudos e não respondem","cuidado","Ser mudo é aqui uma qualidade; a crítica vai para outro lado."]]},{"nivel":1,"tipo":"multi","rot":"Duas propriedades","pergunta":"Quais são as duas coisas que um pregador deve fazer, segundo o sal?","opcoes":[["Louvar o bem",5,"Para o conservar: é a primeira parte do sermão."],["Repreender o mal",5,"Para preservar dele: é a segunda parte."],["Calar-se quando não o ouvem",0,"Vieira faz o contrário: muda de auditório e continua."],["Contar histórias",0,"Conta uma (a de Rimini), mas não é isso que o sal faz."]]},{"nivel":2,"tipo":"classificar","rot":"Louvor ou repreensão","pergunta":"Em que parte do sermão cabe cada frase?","categorias":["Louvor","Repreensão"],"itens":[["Ao menos têm os peixes duas boas qualidades de ouvintes.",0],["Não só vos comeis uns aos outros, mas os grandes comem os pequenos.",1],["Quisestes ser melhor que os outros peixes, e por isso sois mais infeliz que todos.",1],["Começando, pois, pelos vossos louvores, irmãos peixes, bem vos pudera eu dizer que, entre todas as criaturas viventes e sensitivas, vós fostes as primeiras que Deus criou.",0]],"retorno":"Louvar primeiro, repreender depois: é a ordem que o próprio Vieira anuncia com o sal."},{"nivel":3,"tipo":"unica","rot":"O teu elogio","pergunta":"Um elogio a uma coisa que seja crítica a quem ouve, como «ouvem e não falam». Qual cumpre?","opcoes":[["A cadeira é muito útil e confortável, e eu gosto muito dela.","cuidado","Só elogia: ninguém que ouve se sente visado."],["Vocês nunca estão calados e não param de olhar para o telemóvel.","cuidado","Só critica, e de frente: perdeu o rodeio de Vieira."],["Ao menos a cadeira aguenta a aula sem olhar para o telemóvel.","certo","Elogia a cadeira e, no mesmo gesto, critica quem ouve, como «ouvem e não falam»."]]}],"fontes":[["_Sermão de Santo António aos Peixes_ (Internet Archive)","https://archive.org/details/sermao-de-st-antonio-aos-peixes-lusolivros"],["Wikisource, _Sermão de Santo António_ (1654), texto integral","https://pt.wikisource.org/wiki/Serm%C3%A3o_de_Santo_Ant%C3%B3nio_(1654)"]],"imagemData":""};var PERCURSO="https://pedrohfernandes-klk.github.io/pt/m4/";
