var E={"pasta":"Ler-a-fundo","ficheiro":"Camilo-Simao-Ramos.html","id":"camilo-simao-ramos","cor":"#2f2f2f","corEscura":"#bdbdbd","marca":"Ler a fundo · _Amor de Perdição_","titulo":"E se Simão obedecesse ao pai?","subtitulo":"Camilo Castelo Branco, _Amor de Perdição_, 1862, uma história com ramos","niveis":["Ler o que está lá","Escolher","Defender a escolha"],"emblemas":[[0.8,"Leitor de perdição","Escolheste por Simão, viste o que custa cada caminho e sabes o que Camilo escreveu."],[0.5,"Meio caminho","Já percorreste um ramo. Recomeça e vê o que acontece a quem foge."],[0,"A entrar em Viseu","Relê a leitura: duas famílias inimigas, um pai que decide, uma carta no fim."]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Ler","html":"<p><b>Camilo Castelo Branco</b>, o romancista deste módulo, conta em <i>Amor de Perdição</i> (1862) a história de Simão Botelho e Teresa de Albuquerque, filhos de famílias inimigas, em Viseu. O pai de Teresa quer casá-la com o primo, Baltasar Coutinho. Mariana, filha de um ferrador, ama Simão sem lho dizer. No fim, Teresa, fechada num convento, escreve a última carta:</p><p><i>«É já o meu espirito que te falla, Simão. A tua amiga morreu.»</i></p><p class='nota'>A partir daqui, escolhes por Simão. No fim vês o que Camilo escreveu.</p>"},{"nivel":2,"tipo":"ramos","rot":"A história com ramos","pergunta":"Em cada ponto, escolhe um caminho. Podes recomeçar e experimentar outro.","inicio":"a","nos":{"a":{"texto":"Frei Jorge pergunta: «Romeiro, romeiro! quem és tu?» O Romeiro está diante do retrato de D. João de Portugal. O que faz?","opcoes":[["Aponta o bordão para o retrato e diz «Ninguém»","b"],["Diz o nome em voz alta: «Sou D. João de Portugal»","c"],["Cala-se, aceita pão e parte sem dizer quem é","d"]]},"b":{"texto":"Frei Jorge fica a saber o que Madalena já tinha percebido ao ouvir o recado, quando fugiu a gritar: «Estou… estás… perdidas, desonradas… infames!» Se D. João está vivo, o casamento com Manuel não vale e Maria fica sem nome. Manuel de Sousa Coutinho tem de decidir.","opcoes":[["Manuel e Madalena tomam o hábito: morrem para o mundo","e"],["Manuel enfrenta o Romeiro e exige provas","f"]]},"c":{"texto":"Um nome dito em voz alta pode ser contestado. A casa divide-se: Telmo, o velho aio, reconhece-o; Madalena treme; Manuel quer provas. O Romeiro…","opcoes":[["Prova quem é com uma memória que só D. João podia ter","b"],["Recua: «enganei-me», e parte","d"]]},"d":{"fim":true,"texto":"O segredo fica com o Romeiro. Madalena continua casada, Maria continua filha legítima, e todos vivem sobre uma mentira que pode voltar um dia.","nota":"Garrett não escreveu este fim (caminho escrito para este exercício). Na peça, o Romeiro responde «Ninguém» e essa palavra desfaz a família inteira. Pergunta-te: que história é mais forte, a do segredo guardado ou a da palavra dita?"},"e":{"fim":true,"texto":"No ato III, Manuel chora a filha: «Desgraçada filha, que ficas órfã!… órfã de pai e mãe… e de família e de nome». Na capela, o Prior chama-lhe «irmão Luís de Sousa», porque «em tudo quisestes despir o homem velho». Maria, doente, entra: «aqui não morre ninguém sem mim», e morre.","nota":"É o fim de Garrett. A honra do fim do século XVI não deixa a Manuel outra saída, e a peça chama-se pelo nome novo dele: _Frei Luís de Sousa_."},"f":{"fim":true,"texto":"Manuel exige provas; Telmo e o retrato dão-nas. Fica tudo na mesma: D. João está vivo e o casamento não vale. Só se perdeu tempo.","nota":"Garrett não escreveu este fim (caminho escrito para este exercício). Na peça, ninguém pede provas: o retrato prova por si. Se Manuel lutasse, a peça seria um processo em tribunal, não uma tragédia."}}},{"nivel":2,"tipo":"unica","rot":"O que escreveu Camilo","pergunta":"Qual é o caminho que está no romance?","opcoes":[["Simão foge com Teresa e vivem escondidos, longe de Viseu","cuidado","Teresa só sai de casa do pai para o convento, de onde escreve a última carta."],["Simão mata Baltasar, é preso e degredado; Teresa morre no convento","certo","Sim: Teresa escreve a última carta a morrer, e Simão lê-a a caminho da Índia."],["Simão obedece ao pai, deixa Teresa e fica a estudar em Coimbra","cuidado","Nem Simão cede nem Teresa: por isso ela acaba no convento e ele no degredo."]]},{"nivel":3,"tipo":"unica","rot":"Defende o caminho","pergunta":"Qual destas frases defende melhor o caminho de Camilo: porque é que o romance precisa dele?","opcoes":[["Sem a separação e a última carta não há «amor de perdição»: a história é a de dois que se perdem por amar.","certo","Liga o caminho ao título: sem perda não há amor de perdição."],["Se Simão obedecesse ao pai, Teresa casava com o primo e ficavam todos felizes: o livro acabava bem.","cuidado","Descreve o caminho de obedecer, não defende o de Camilo; e «todos felizes» não está no texto."],["O romance precisa do caminho de Camilo porque foi o que ele escreveu em 1862 e não se pode mudar.","cuidado","Ser o que Camilo escreveu não diz porque é que a história precisa dele."]]}],"fontes":[["Camilo Castelo Branco, _Amor de Perdição_, texto integral (Project Gutenberg n.º 16425)","https://www.gutenberg.org/ebooks/16425"],["Amor de Perdição (Wikipédia)","https://pt.wikipedia.org/wiki/Amor_de_Perdi%C3%A7%C3%A3o"]],"imagemData":""};var PERCURSO="https://pedrohfernandes-klk.github.io/pt/m5/";
