var E={"pasta":"Ler-a-fundo","ficheiro":"Cesario-Horas-Mortas.html","id":"cesario-noite","cor":"#2f2f2f","corEscura":"#bdbdbd","marca":"Ler a fundo · M6 Cesário","titulo":"Da «Noite Fechada» às «Horas Mortas»","subtitulo":"Cesário Verde, «O Sentimento dum Ocidental», 1887 · II e IV","niveis":["Ler o que está lá","Ler nas entrelinhas","Fazer com o que leste"],"emblemas":[[0.8,"Leitor da cidade-prisão","Viste as grades, o palácio e o casebre, e o sonho a ser cortado pelo «Mas»."],[0.5,"Bom começo","Já vês a noite. Repara na palavra que devolve o sujeito à rua: «Mas»."],[0,"A entrar na noite","Relê: a cidade fecha-se como uma cadeia."]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Ler","html":"<p><b>II</b> — «Noite Fechada»:</p><p><i>Toca-se as grades, nas cadeias. Som<br>Que mortifica e deixa umas loucuras mansas!<br>O aljube, em que hoje estão velhinhas e creanças,<br>Bem raramente encerra uma mulher de «dom»!</i></p><p>[…]</p><p><i>E eu sonho o Colera, imagina a Febre,<br>N'esta accumulação de corpos enfezados;<br>Sombrios e espectraes recolhem os soldados;<br>Inflamma-se um palacio em face de um casebre.</i></p><p><b>IV</b> — «Horas Mortas»:</p><p><i>Se eu não morresse, nunca! E eternamente<br>Buscasse e conseguisse a perfeição das cousas!<br>Esqueço-me a prever castissimas esposas,<br>Que aninhem em mansões de vidro transparente!</i></p><p>[…]</p><p><i>Mas se vivemos, os emparedados,<br>Sem arvores, no valle escuro das muralhas!...<br>Julgo avistar, na treva, as folhas das navalhas<br>E os gritos de soccorro ouvir estrangulados.</i></p><p><i>E, enorme, n'esta massa irregular<br>De predios sepulchraes, com dimensões de montes,<br>A Dôr humana busca os amplos horisontes,<br>E tem marés, de fel, como um sinistro mar!</i></p><p class=\"nota\"><b>mortifica</b> — atormenta · <b>aljube</b> — prisão · <b>mulher de «dom»</b> — senhora de família nobre · <b>enfezados</b> — raquíticos · <b>emparedados</b> — fechados entre paredes · <b>fel</b> — amargura · <b>imagina</b> — assim na edição de 1887; muitas edições corrigem para «imagino»</p>","links":[["_O Livro de Cesário Verde_ (Project Gutenberg n.º 8698)","https://www.gutenberg.org/ebooks/8698"]]},{"nivel":1,"tipo":"unica","rot":"Quem está preso","pergunta":"«O aljube, em que hoje estão velhinhas e creanças, / Bem raramente encerra uma mulher de “dom”!» O que denuncia o verso?","opcoes":[["Que a prisão está quase vazia, porque já ninguém comete crimes","cuidado","Está cheia: «velhinhas e creanças». O que falta lá dentro é a mulher de «dom»."],["Que as mulheres de família nobre são as mais honestas da cidade","cuidado","Não é isso: é quem é apanhado e quem fica de fora."],["Que a prisão é para os pobres: as senhoras nobres nunca lá entram","certo","Crítica social em dois versos: velhinhas e crianças presas, as de «dom» de fora."]]},{"nivel":2,"tipo":"ordenar","rot":"Do sonho ao «Mas»","pergunta":"Põe por ordem os momentos da parte IV.","itens":["O sujeito sonha não morrer nunca e buscar a perfeição","Imagina esposas puras em mansões de vidro","«Mas se vivemos, os emparedados»: volta à cidade sem árvores","Vê navalhas e ouve gritos na treva","A Dor humana, enorme, como um mar de fel"],"retorno":"Sonho, viragem, realidade, dor: o «Mas» é a dobradiça de todo o poema."},{"nivel":2,"tipo":"unica","rot":"O mar de fel","pergunta":"O poema começa (I, «Ave-Marias») com «o Tejo, a maresia». No fim: «A Dôr humana busca os amplos horisontes, / E tem marés, de fel, como um sinistro mar!» O que liga este fim a esse início?","opcoes":[["Nada: é uma imagem nova, sem ligação nenhuma ao que veio antes","cuidado","O Tejo e a maresia estão lá desde a primeira estrofe do poema."],["O Tejo e a maresia voltam como mar de fel: o poema fecha em círculo","certo","E a dor já não é só do sujeito: é «humana»."],["O sujeito prepara-se para embarcar nesse mar e partir de Lisboa","cuidado","Não embarca: fica na cidade, «emparedado», e o mar é a dor."]]},{"nivel":3,"tipo":"unica","rot":"Palácio e casebre, hoje","pergu