var E={"pasta":"Ler-a-fundo","ficheiro":"Gramatica-Era-Fui.html","id":"gram-valores-pessoa","cor":"#2f4f6f","corEscura":"#9bbbd8","marca":"Gramática em contexto · M7 Pessoa","titulo":"Era, fui, talvez","subtitulo":"Valor aspetual e valor modal em versos de Pessoa","niveis":["Reconhecer","Provar com um teste","Usar na tua escrita"],"emblemas":[[0.8,"Relógio afinado","Sabes dizer se a situação acabou, dura ou se repete, e o que pensa quem fala."],[0.5,"Bom caminho","Acertaste no essencial. Repete as perguntas: acabou? dura? repete-se?"],[0,"A acertar o relógio","Volta à primeira pergunta: a situação está acabada ou a decorrer?"]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Três versos","html":"<p>Os versos vêm de poemas que já leste.</p><p class=\"verso\"><b>A.</b> «Eu era feliz e ninguém estava morto.» (Campos)</p><p class=\"verso\"><b>B.</b> «Cumpriu-se o Mar, e o Império se desfez.» (<i>Mensagem</i>)</p><p class=\"verso\"><b>C.</b> «Julgando-se feliz talvez» (ortónimo)</p><p class=\"nota\"><b>aspeto</b>: acabou (perfetivo), dura (imperfetivo), é costume (habitual), repete-se vezes contadas (iterativo), vale sempre (genérico)<br><b>modalidade</b>: certeza ou probabilidade (epistémica), dever ou conselho (deôntica), avaliação (apreciativa)</p>","links":[["Arquivo Pessoa","http://arquivopessoa.net"]]},{"nivel":1,"indice":1,"tipo":"unica","rot":"Era feliz","pergunta":"Em A, «era» mostra a felicidade…","opcoes":[["a durar, vista por dentro: imperfetivo","certo","Sim: o imperfeito deixa o passado aberto."],["acabada, vista de fora: perfetivo","cuidado","Teste: isso seria _fui feliz_."],["repetida três vezes: iterativo","cuidado","Teste: não há vezes contadas."]]},{"nivel":1,"indice":2,"tipo":"unica","rot":"Cumpriu-se","pergunta":"Em B, «Cumpriu-se» tem valor…","opcoes":[["imperfetivo: a situação está a decorrer","cuidado","Teste: não está a decorrer; já aconteceu."],["perfetivo: a situação está acabada","certo","Sim: o mar está cumprido; falta o resto."],["genérico: vale para sempre e para todos","cuidado","Teste: não vale para sempre nem para todos."]]},{"nivel":2,"tipo":"multi","rot":"Pistas, não provas","pergunta":"Que pistas ajudam a dar o valor aspetual? Toca nas que servem.","opcoes":[["O tempo do verbo: perfeito ou imperfeito",5,"É a primeira pista."],["Expressões como «três vezes», «todos os dias», «sempre»",5,"Dizem se se repete e como."],["Perguntar: acabou, dura ou repete-se?",5,"É o teste mais seguro."],["O tamanho do verso",0,"O tamanho não diz o aspeto."]]},{"nivel":2,"tipo":"classificar","rot":"O que pensa quem fala","pergunta":"Diz a modalidade de cada verso.","categorias":["epistémica","deôntica","apreciativa"],"itens":[["Julgando-se feliz talvez",0],["Segue o teu destino",1],["Triste de quem vive em casa",2],["Nunca serei nada",0],["Tem que passar além da dor",1]],"retorno":"Certeza ou dúvida, dever ou conselho, avaliação: três atitudes de quem fala."},{"nivel":3,"indice":5,"tipo":"unica","rot":"Duas vezes","pergunta":"Qual destes pares diz a mesma lembrança, primeiro com _estava_ e depois com _estive_?","opcoes":[["No primeiro dia do curso eu estava nervoso. / No primeiro dia do curso eu estive nervoso.","certo","A mesma lembrança, só muda o verbo: é o par que a encomenda pede."],["No primeiro dia do curso eu estava nervoso. / No último dia do curso eu estive contente.","cuidado","Mudou o verbo, mas mudou também a lembrança: já não é a mesma."],["No primeiro dia do curso eu estava nervoso. / No primeiro dia do curso eu fico nervoso.","cuidado","O segundo verbo está no presente: não é _fui_ nem _estive_."]]},{"nivel":3,"tipo":"unica","rot":"Primeira frase","pergunta":"«No primeiro dia do curso eu estava nervoso.» Que valor aspetual tem «estava»?","opcoes":[["Perfetivo: o nervosismo acabou nesse dia.","cuidado","Acabar é o valor de «estive», não de «estava»."],["Habitual: ficava nervoso todos os dias.","cuidado","Não há costume: é um só dia, o primeiro."],["Imperfetivo: o nervosismo dura, sem fim marcado.","certo","«Estava» mostra o estado a durar, como «era feliz» em A."]]},{"nivel":3,"tipo":"unica","rot":"Segunda frase","pergunta":"«No primeiro dia do curso eu estive nervoso.» Que valor aspetual tem «estive»?","opcoes":[["Imperfetivo: dura e não se sabe quando acabou.","cuidado","Durar sem fim é «estava»; «estive» fecha o estado."],["Perfetivo: começou e acabou, fechado nesse dia.","certo","«Estive» mostra o estado como acabado, como «Cumpriu-se» em B."],["Iterativo: repetiu-se, dia após dia, ao longo do curso.","cuidado","Não há repetição: é uma vez, um dia."]]},{"nivel":3,"tipo":"unica","rot":"O que muda","pergunta":"Entre «estava nervoso» e «estive nervoso», o que muda no sentido?","opcoes":[["Nada: é só uma questão de estilo e de gosto.","cuidado","Muda o aspeto: a mesma lembrança vista a durar ou vista acabada."],["O tempo: uma está no passado, a outra no presente.","cuidado","Ambas são passado; o que muda é o aspeto, não o tempo."],["O olhar: o estado visto a durar ou já acabado.","certo","É isso: imperfetivo abre a cena, perfetivo fecha-a."]]}],"fontes":[["Arquivo Pessoa","http://arquivopessoa.net"]],"imagemData":""};var PERCURSO="https://pedrohfernandes-klk.github.io/pt/m7/";
