var E={"pasta":"Ler-a-fundo","ficheiro":"Gramatica-Carregou-Carregava.html","id":"gram-aspeto-memorial","cor":"#5a4a2f","corEscura":"#d8c39b","marca":"Gramática em contexto · _Memorial do Convento_","titulo":"Carregou, carregava","subtitulo":"O fio que liga as frases e o relógio de cada verbo","niveis":["Reconhecer","Provar com um teste","Usar na tua escrita"],"emblemas":[[0.8,"Fio e relógio","Sabes o que liga as frases e o que cada verbo diz do tempo."],[0.5,"Bom caminho","Acertaste no essencial. Repete as perguntas: acabou? dura? repete-se?"],[0,"A dar corda","Volta à primeira pergunta: a situação está acabada ou a decorrer?"]],"passos":[{"nivel":1,"tipo":"leitura","rot":"Três frases","html":"<p>As frases foram escritas para este exercício, à maneira de Saramago. Não são do romance.</p><p><b>A.</b> Chegaram os homens a Mafra, e ali ficaram anos.</p><p><b>B.</b> Todas as manhãs o capataz contava-os, um a um.</p><p><b>C.</b> Isto sabia-o já, quem manda não tem pressa.</p><p class=\"nota\"><b>aspeto</b>: acabou (perfetivo), dura (imperfetivo), é costume (habitual), repete-se vezes contadas (iterativo), vale sempre (genérico)<br><b>coesão</b>: anáfora (retoma o que já foi dito), catáfora (anuncia o que vem), conector (liga e diz a relação)</p>"},{"nivel":1,"tipo":"unica","rot":"Ali","pergunta":"Em A, «ali»…","opcoes":[["retoma «Mafra»: é uma anáfora","certo","Sim: a palavra só se percebe com o que veio antes."],["anuncia o que vem a seguir: é uma catáfora","cuidado","Teste: o lugar já foi dito antes de «ali»."],["liga duas orações: é um conector","cuidado","Teste: quem liga as orações é «e»."]]},{"nivel":1,"indice":2,"tipo":"unica","rot":"Todas as manhãs","pergunta":"Em B, «contava-os» tem valor…","opcoes":[["habitual: é costume","certo","Sim: «todas as manhãs» diz que se repete sem número certo."],["iterativo: vezes contadas","cuidado","Teste: não se diz quantas vezes."],["perfetivo: está acabado","cuidado","Teste: isso seria _contou-os_."]]},{"nivel":2,"tipo":"classificar","rot":"Cinco relógios","pergunta":"Dá o valor aspetual a cada frase.","categorias":["perfetivo","imperfetivo","habitual","iterativo","genérico"],"itens":[["O rei marcou a data.",0],["A pedra esperava.",1],["O capataz fazia a chamada todas as manhãs.",2],["Manuel bateu três vezes à porta.",3],["Quem manda não tem pressa.",4]],"retorno":"Acabou, dura, é costume, repete-se vezes contadas, vale sempre: cinco relógios."},{"nivel":3,"tipo":"unica","rot":"Duas frases tuas","pergunta":"Qual destas segue a encomenda: o mesmo gesto, perfetivo e depois habitual, ligados por um conector?","opcoes":[["Ontem montei a luz do palco e depois arrumei os cabos.","cuidado","Dois gestos acabados, os dois perfetivos: falta o costume, e o gesto não é o mesmo."],["Ontem montei a luz do palco em dez minutos, mas costumo demorar uma hora.","certo","O mesmo gesto, dito de duas maneiras e ligado por um conector: é a encomenda."],["Costumo montar a luz do palco. Todas as semanas faço o mesmo.","cuidado","As duas dizem costume e nada as liga: falta o perfetivo e o conector."]]},{"nivel":3,"indice":6,"tipo":"unica","rot":"A primeira frase","pergunta":"Em «Ontem montei a luz do palco em dez minutos», o valor aspetual é…","opcoes":[["habitual: é o que faço sempre.","cuidado","«Ontem» e «montei» contam um gesto acabado, uma vez só: não é costume."],["imperfetivo: o gesto ainda dura.","cuidado","«Montei» já acabou; se durasse, seria _montava_."],["perfetivo: o gesto acabou.","certo","É isso: «ontem montei» é uma ação acabada, com princípio e fim."]]},{"nivel":3,"indice":7,"tipo":"unica","rot":"A segunda frase","pergunta":"Em «mas costumo demorar uma hora», o valor aspetual é…","opcoes":[["habitual: é costume.","certo","«Costumo» diz um costume, sem contar as vezes: habitual."],["iterativo: repete-se vezes contadas.","cuidado","Iterativo seria _demorei uma hora três vezes_; «costumo» não conta as vezes."],["perfetivo: acabou.","cuidado","Nada acabou: «costumo» vale para o que faço de hábito."]]},{"nivel":3,"indice":8,"tipo":"unica","rot":"O conector","pergunta":"Em «Ontem montei a luz do palco em dez minutos, mas costumo demorar uma hora», o que diz «mas» da relação entre as duas partes?","opcoes":[["Que a segunda é a causa da primeira.","cuidado","Causa seria _porque_; «mas» não explica, opõe."],["Que a segunda contraria o que a primeira fazia esperar.","certo","É isso: ontem em dez minutos, mas de costume uma hora. «Mas» marca oposição."],["Que a segunda vem depois da primeira, no tempo.","cuidado","Tempo seria _depois_ ou _então_; «mas» marca oposição, não ordem."]]}],"fontes":[["_Dicionário Terminológico_","https://dt.dge.mec.pt"]],"imagemData":""};var PERCURSO="https://pedrohfernandes-klk.github.io/pt/m9/";
