const memory=new Map();function storage(id){if(memory.has(id))return memory.get(id);try{const value=JSON.parse(localStorage.getItem('pt-exame-sessao-'+id)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch(_){return {};}}
function store(id,v){memory.set(id,v);try{localStorage.setItem('pt-exame-sessao-'+id,JSON.stringify(v));}catch(_){/* The timer remains usable in this tab. */}}
function state(){return storage(session.id);}
function phaseLabel(i){return session&&session.video&&i===1?'Ver e aplicar':phaseNames[i];}
function duration(s,p){return [5,8,s.writing.minutes,27-s.writing.minutes,5][p]*60;}
function random(a){const b=a.slice();for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function warmIds(reset){const st=state(),valid=new Set(session.warmup.map(q=>q.id));if(!reset&&Array.isArray(st.warm)&&st.warm.length===2&&st.warm.every(x=>valid.has(x)))return st.warm;

