/* Textos compostos como no exame (27/10/2026): versos e estrofes, parágrafos numerados, falas de teatro, notas numeradas e crédito. Marcação dos dados: {termo|glosa} e _itálico_. */
function inline(t,notes){let h=e(t).replace(/_([^_]+)_/g,'<i>$1</i>');if(notes)h=h.replace(/\{([^|{}]+)\|([^{}]+)\}/g,(m,termo,glosa)=>{notes.push([termo,glosa]);return '<span class="glosa">'+termo+'<sup>'+notes.length+'</sup></span>';});return h;}
function fala(h){h=h.replace(/\(([^()]*)\)/g,'<span class="dida">($1)</span>');return h.replace(/^([A-ZÁÉÍÓÚÂÊÔÃÕÇ]{3,})((?:,[^:<]{1,60})?):\s*/,(m,quem,como)=>'<span class="fala-quem">'+quem+'</span>'+(como?'<span class="fala-como">'+como+'</span>':'')+': ');}
function passage(p){const notes=[];let corpo='',n=0;
 if(p.form==='verso')corpo='<div class="pass-verso">'+p.stanzas.map(st=>st.length===1&&st[0]==='[…]'?'<p class="pass-omissao"><span aria-hidden="true">[…]</span><span class="of-so-leitor">Versos omitidos.</span></p>':'<p class="estrofe">'+st.map(l=>{n++;return '<span class="vl">'+(n%5===0?'<span class="vn" aria-hidden="true">'+n+'</span>':'')+inline(l,notes)+'</span>';}).join('')+'</p>').join('')+'</div>';
 else corpo='<div class="pass-prosa'+(p.form==='cena'?' pass-cena':'')+'">'+p.paragraphs.map(q=>{const h=inline(q.text,notes);return '<p class="par">'+(q.n?'<span class="par-n">['+e(q.n)+']</span> ':'')+(p.form==='cena'?fala(h):h)+'</p>';}).join('')+'</div>';
 return '<article class="passagem" data-forma="'+e(p.form)+'"><header class="pass-cab">'+(p.label?'<span class="pass-letra">Texto '+e(p.label)+'</span>':'')+'<h4 class="pass-nome">'+inline(p.head)+'</h4></header>'+corpo+(notes.length?'<ol class="notas" aria-label="Vocabulário">'+notes.map(x=>'<li><span class="nota-t">'+x[0]+'</span> '+x[1]+'</li>').join('')+'</ol>':'')+'<p class="pass-credito">'+inline(p.credit)+'</p>'+(p.note?'<p class="pass-nota">'+e(p.note)+(p.link?' '+link({label:'Abrir a lição ↗',url:p.link}):'')+'</p>':'')+'</article>';}
/* 29/10/2026: no aquecimento, o texto de apoio aparece sem as notas de vocabulário; várias perguntas de aquecimento perguntam o sentido de uma palavra pelo contexto, e a nota dava a resposta. As notas voltam na fase Ler. */
const semGlosa=t=>String(t).replace(/\{([^|{}]+)\|[^{}]+\}/g,'$1');
function passageSemNotas(p){return passage(Object.assign({},p,Array.isArray(p.stanzas)?{stanzas:p.stanzas.map(st=>st.map(semGlosa))}:{},Array.isArray(p.paragraphs)?{paragraphs:p.paragraphs.map(q=>Object.assign({},q,{text:semGlosa(q.text)}))}:{}));}
function source(s,aquecer){const ps=Array.isArray(s.source.passages)?s.source.passages:null;return '<section class="source'+(ps?' source-textos':'')+'"><h3>'+e(s.source.title)+'</h3><p class="context">'+e(s.source.context)+'</p>'+(ps?'<div class="passagens">'+ps.map(aquecer?passageSemNotas:passage).join('')+'</div>'+(aquecer?'<p class="small">As notas de vocabulário aparecem na fase Ler.</p>':''):s.source.excerpt?'<blockquote>'+e(s.source.excerpt)+'</blockquote>':'')+'<cite>'+e(s.source.author)+'</cite><p class="note">'+e(s.source.note)+'</p><div class="source-links">'+(s.source.original?'':link({label:'Abrir a leitura de apoio ↗',url:s.source.url}))+(s.resources||[]).map(link).join('')+'</div></section>';}
function question(q){const selected=entry&&entry.answers[q.id],answered=!!selected&&Number.isInteger(selected.choice)&&selected.choice>=0&&selected.choice<q.options.length;
 return '<section class="question" data-question="'+e(q.id)+'"><h3>'+e(q.q)+'</h3><div class="choices">'+random(q.options.map((text,index)=>({text,index}))).map(o=>'<button type="button" class="choice'+(answered&&o.index===q.answer?' correct':answered&&o.index===selected.choice?' incorrect':'')+'" data-choice="'+o.index+'"'+(answered?' disabled':'')+'>'+e(o.text)+'</button>').join('')+'</div>'+(answered?'<p class="feedback"><b>'+(selected.choice===q.answer?'Certo.':'Revê esta escolha.')+'</b> '+e(q.feedback)+'</p>':'')+'</section>';}
function notes(){if(projected)return '';return '<section data-private><label class="field-label" for="notes">O que preciso de rever?</label><textarea id="notes" data-note="notes" maxlength="20000" placeholder="Regista uma dúvida, uma descoberta ou uma indicação do docente.">'+e(entry.notes)+'</textarea><label class="field-label" for="revised">A minha versão revista · opcional</label><textarea id="revised" data-note="revisedText" maxlength="60000" placeholder="Podes escrever aqui a revisão ou fotografar a versão que fizeste no papel.">'+e(entry.revisedText)+'</textarea><div class="save-row"><button type="button" data-action="save">Guardar no dossiê</button><span class="save-status" data-save-status>As notas e fotografias ficam neste dispositivo.</span></div></section>';}
function checklist(){return '<div class="checklist">'+session.writing.criteria.map((text,i)=>'<label><input type="checkbox" data-check="'+i+'"'+(entry.checklist['c'+i]?' checked':'')+'>'+e(text)+'</label>').join('')+'</div>';}
function corrections(){const c=session.correction;return '<p class="small">Proposta comentada para estudar e discutir. Outras respostas fundamentadas podem ser válidas.</p><h3>'+e(c.kind||'Orientação de correção')+'</h3><blockquote class="model">'+e(c.model)+'</blockquote><ol class="correction-steps">'+c.steps.map(x=>'<li><b>'+e(x.label)+'</b>'+e(x.detail)+'</li>').join('')+'</ol><h3>O que evitar</h3>'+list(c.pitfalls)+'<h3>Experimenta corrigir</h3>'+question(c.check)+'<h3>Revê a tua resposta</h3>'+checklist();}
function videoLesson(){const v=session.video;return '<h2 class="phase-title">Vê, pausa, põe à prova.</h2><p>'+e(v.intro)+'</p><p class="small">'+e(v.title)+' · '+e(v.author)+' · '+link({label:'Abrir vídeo completo ↗',url:v.url})+'</p><div class="video-clips">'+v.clips.map((c,i)=>'<section class="video-clip"><h3>'+e(c.label)+'</h3><p>'+e(c.observe)+'</p>'+(v.embeddable===false?'<p>'+link({label:'Abrir este trecho no YouTube ↗',url:v.url+'&t='+c.start+'s'})+'</p>':'<div class="video-player" data-video-slot="'+i+'"><button type="button" data-video="'+i+'">Carregar este trecho</button></div>')+'</section>').join('')+'</div>'+(v.playbackNote?'<p class="small">'+e(v.playbackNote)+'</p>':'')+'<details class="video-fallback"'+(v.embeddable===false?' open':'')+'><summary>Sem vídeo? Trabalhar a mesma ideia em texto</summary><p>'+e(v.fallback)+'</p></details><p class="small">'+e(v.note)+'</p><h3>Compreender e aplicar</h3>'+v.questions.map(question).join('')+'<h3>Dois casos para experimentar</h3>'+source(session);}
function phaseContent(){if(phase===0)return '<h2 class="phase-title">Ativa o que sabes.</h2><p>Duas perguntas para começar. Responde e lê a explicação, mesmo quando acertas. Podes consultar o texto antes de responder.</p><details><summary>Consultar leitura de apoio</summary>'+source(session,true)+'</details><div id="questions">'+currentQuestions().map(question).join('')+'</div><button type="button" class="text-button" data-action="another">Outro aquecimento</button>';
 if(phase===1&&session.video)return videoLesson();
 if(phase===1)return '<h2 class="phase-title">Lê com uma pergunta em mente.</h2><p>'+e(session.focus)+'</p>'+source(session)+'<p class="callout">Sublinha no texto duas pistas que poderão sustentar a tua resposta. Na projeção, abre a leitura de apoio quando precisares do recorte completo.</p>'+alternatives();
 if(phase===2)return '<h2 class="phase-title">'+e(session.writing.title)+'</h2><p class="writing-target">'+session.writing.minutes+' minutos · '+e(session.writing.target)+'</p><p class="writing-task">'+e(session.writing.prompt)+'</p>'+list(session.writing.instructions)+'<h3>Antes de entregar</h3>'+list(session.writing.criteria)+'<p class="callout">Responde no caderno ou em papel. Identifica a sessão e deixa espaço para a revisão.</p>';
 if(phase===3)return '<h2 class="phase-title">Da resposta à revisão.</h2><p>Compara a tua resposta com os critérios. Identifica primeiro o que funciona e depois o que precisas de alterar.</p><button type="button" class="primary" data-action="reveal" aria-expanded="'+revealed+'" aria-controls="correction">'+(revealed?'Recolher proposta de correção':'Mostrar proposta de correção')+'</button><div id="correction"'+(revealed?'':' hidden')+'>'+(revealed?corrections():'')+'</div>'+(!projected?notes():'');
 return '<h2 class="phase-title">Leva uma melhoria contigo.</h2><p class="writing-task">'+e(session.exit)+'</p>'+checklist()+(!projected?notes()+'<h3>Regista a resposta que fizeste no papel</h3><p class="small">Junta até quatro fotografias legíveis a esta sessão. JPEG, PNG ou WebP, até 8 MiB por imagem. São guardadas com o enunciado e a correção, neste dispositivo.</p><button type="button" data-action="photos">Adicionar fotografias</button><input type="file" id="photo-input" accept="image/jpeg,image/png,image/webp" multiple hidden><div id="session-photos" class="photos"></div>':'<p class="callout">No teu dispositivo, abre o dossiê desta sessão para guardar as fotografias e a versão revista.</p>')+'<div class="dossier-actions"><a class="button primary" href="#inicio">Voltar às sessões</a>'+(!projected?'<a class="button" href="#dossie">Abrir o meu dossiê</a>':'')+'</div>';}
function alternatives(){if(!session.alternatives||!session.alternatives.length)return '';return '<details class="alternatives"><summary>Outra obra no teu percurso?</summary><p class="small">Escolhe a obra que estudaste. A tarefa mantém a competência, com as adaptações indicadas.</p><ul>'+session.alternatives.map(x=>'<li><b>'+e(x.label)+'</b><p>'+e(x.instruction)+'</p>'+link({label:'Referência e leitura ↗',url:x.url})+'</li>').join('')+'</ul></details>';}
function renderSession(){document.title=session.title+' · Preparação de exame';document.body.dataset.fase=phaseKeys[phase];const index=data.sessions.indexOf(session),previous=data.sessions[index-1],next=data.sessions[index+1];
 app.innerHTML='<div class="session-heading"><p class="eyebrow">Sessão '+String(session.order).padStart(2,'0')+' · '+e(session.group)+' · 45 minutos</p><h1>'+e(session.title)+'</h1><p>'+e(session.focus)+'</p></div><nav class="session-nav" aria-label="Percurso sugerido">'+(previous?'<a href="#'+previous.id+'/aquecer">← '+e(previous.title)+'</a>':'<a href="#inicio">← Todas as sessões</a>')+(next?'<a href="#'+next.id+'/aquecer">'+e(next.title)+' →</a>':'<a href="#inicio">Todas as sessões →</a>')+'</nav><ol class="phase-nav" aria-label="Fases da sessão">'+phaseNames.map((original,i)=>{const name=phaseLabel(i);return '<li><a data-fase="'+phaseKeys[i]+'" href="#'+session.id+'/'+phaseKeys[i]+'"'+(i===phase?' aria-current="step"':'')+'><span class="fase-n" aria-hidden="true">0'+(i+1)+'</span>'+e(name)+'<small>'+duration(session,i)/60+' min</small></a></li>';}).join('')+'</ol><div class="session-layout"><section class="phase-content">'+phaseContent()+'<nav class="phase-actions" aria-label="Avançar na sessão">'+(phase?'<a class="button" href="#'+session.id+'/'+phaseKeys[phase-1]+'">← '+phaseLabel(phase-1)+'</a>':'<span></span>')+(phase<4?'<a class="button primary" href="#'+session.id+'/'+phaseKeys[phase+1]+'">'+phaseLabel(phase+1)+' →</a>':'')+'</nav></section><aside class="session-tools" aria-label="Relógio e materiais"><div class="session-relogio" id="relogio-fase"></div><div class="tool-links"><button type="button" data-action="print">Imprimir enunciado</button><button type="button" data-action="print-correction">Imprimir correção</button>'+(!projected?'<a href="#dossie">O meu dossiê →</a>':'')+'<a href="#cobertura">Programa e fontes →</a></div></aside></div>';
 bindSession();mountClock();if(phase===4&&!projected)renderPhotos().catch(error);}
/* Relógio do aluno (27/10/2026): duração escolhida até ao tempo da fase; duas pausas; depois, parar recomeça.
   29/10/2026: um relógio por sessão e fase, guardado em memória. Voltar a desenhar a fase (proposta de correção, outro aquecimento)
   volta a pôr o mesmo relógio, mesmo sem armazenamento; sair da fase com o relógio a contar conta como pausa, como no laboratório. */
function mountClock(){const slot=document.getElementById('relogio-fase');if(!slot||!window.EPIRelogio)return;const key=session.id+'-'+phaseKeys[phase];
 if(!clocks[key]){const host=document.createElement('div');clocks[key]={box:host,api:EPIRelogio.criar(host,{max:duration(session,phase)/60,passo:1,rotulo:'Tempo para '+(session.video&&phase===1?'ver e aplicar':phaseNames[phase].toLowerCase()),chave:'pt-exame-relogio-'+key})};}
 slot.replaceChildren(clocks[key].box);clock=clocks[key].api;clock.atualizar();}
function leaveClock(){if(!clock)return;const c=clock;clock=null;if(!c.estado().corre)return;c.pausar();const s=c.estado();message(s.iniciado?'Relógio da fase em pausa (pausa '+s.pausasUsadas+' de 2).':'Usaste as duas pausas: o relógio da fase voltou ao início.');}
function bindSession(){bindQuestionButtons();
 app.querySelectorAll('[data-video]').forEach(b=>b.addEventListener('click',()=>{const c=session.video&&session.video.clips[Number(b.dataset.video)];if(!c||!/^[A-Za-z0-9_-]{11}$/.test(c.id)||!Number.isInteger(c.start)||!Number.isInteger(c.end)||c.start<0||c.end<=c.start)return;const f=document.createElement('iframe');f.src='https://www.youtube-nocookie.com/embed/'+c.id+'?start='+c.start+'&end='+c.end+'&rel=0';f.title=c.label+' · '+session.video.author;f.allow='encrypted-media; picture-in-picture; fullscreen';f.allowFullscreen=true;f.referrerPolicy='strict-origin-when-cross-origin';b.parentElement.replaceChildren(f);}));
 app.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action).catch(error)));
 app.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>{entry[el.dataset.note]=el.value;scheduleSave();}));
 app.querySelectorAll('[data-check]').forEach(el=>el.addEventListener('change',()=>{entry.checklist['c'+el.dataset.check]=el.checked;queueSave();}));const file=document.getElementById('photo-input');if(file)file.addEventListener('change',async()=>{const id=session.id,snapshot=structuredClone(session),token=viewToken,files=Array.from(file.files);try{await flush();const saved=await D.addPhotos(id,files,snapshot);if(token===viewToken){entry=saved;await renderPhotos();}message('Fotografias guardadas com esta sessão.');}catch(err){error(err);}finally{file.value='';}});}
function bindQuestionButtons(){/* Rebind only the replaced question; unaffected controls keep their handlers. */app.querySelectorAll('[data-choice]:not(:disabled)').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>{const qid=b.closest('[data-question]').dataset.question,q=currentQuestions().find(x=>x.id===qid);if(!q||entry.answers[qid])return;entry.answers[qid]={choice:Number(b.dataset.choice),correct:Number(b.dataset.choice)===q.answer};b.closest('[data-question]').outerHTML=question(q);bindQuestionButtons();queueSave();});});}
async function act(action){if(action==='reveal'){revealed=!revealed;renderSession();}
 else if(action==='another'){warmIds(true);session.warmup.forEach(q=>delete entry.answers[q.id]);renderSession();await queueSave();}
 else if(action==='save'){await queueSave();message('Registo guardado neste dispositivo.');}
 else if(action==='photos')document.getElementById('photo-input').click();
 else if(action==='print'||action==='print-correction')printSession(action==='print-correction');}
function printSession(correction){const s=session;document.getElementById('print-sheet').innerHTML='<p class="print-meta">Português · Preparação de exame · Sessão '+s.order+' · 45 minutos</p><h1>'+e(s.title)+'</h1><p>'+e(s.focus)+'</p>'+source(s)+'<h2>'+e(s.writing.title)+'</h2><p>'+e(s.writing.prompt)+'</p><p>'+e(s.writing.target)+'</p>'+list(s.writing.instructions)+'<h2>Critérios de revisão</h2>'+list(s.writing.criteria)+(correction?'<h2>Proposta de correção</h2><blockquote>'+e(s.correction.model)+'</blockquote>'+list(s.correction.steps.map(x=>x.label+': '+x.detail)):'<div class="answer-lines" aria-hidden="true"></div>');window.print();}
async function renderPhotos(){const el=document.getElementById('session-photos');if(!el||projected)return;const token=viewToken,id=session.id;const record=await D.getEntry(id);if(token!==viewToken||!entry||entry.sessionId!==id)return;revoke();entry.photos=record?record.photos:[];el.innerHTML=(entry.photos||[]).map(p=>photoCard(p,session.id,true)).join('');el.querySelectorAll('[data-remove-photo]').forEach(b=>b.addEventListener('click',async()=>{try{if(!confirm('Remover esta fotografia do dossiê deste dispositivo?'))return;await D.removePhoto(session.id,b.dataset.removePhoto);await renderPhotos();message('Fotografia removida.');}catch(err){error(err);}}));}
function photoCard(p,id,editable){const u=D.photoURL(p);objectURLs.push(u);return '<figure class="photo"><a href="'+e(u)+'" target="_blank" rel="noopener"><img src="'+e(u)+'" alt="Fotografia da resposta: '+e(p.name)+'" loading="lazy"></a><figcaption>'+e(p.name)+' · '+(p.size/1024/1024).toFixed(1)+' MiB</figcaption>'+(editable?'<button type="button" class="text-button danger" data-remove-photo="'+e(p.id)+'">Remover fotografia</button>':'')+'</figure>';}
function catalogue(){document.title='Preparação de exame · Português';app.innerHTML='<section class="hero"><div><p class="eyebrow">Português · 10.º–12.º ano</p><h1>Da leitura<br>à resposta<span>.</span></h1><p class="lead">Uma sessão, uma competência em foco. Aquece no ecrã, escreve no papel e revê com critérios. Junta as fotografias ao teu dossiê para voltar ao que aprendeste.</p></div><div class="clock-art" aria-label="45 minutos por sessão"><b>45′</b><span>por sessão</span><i aria-hidden="true"></i></div></section><div class="intro-row"><p><b>Percurso sugerido e acesso livre.</b> Cada sessão reserva 10–20 minutos para escrever e tempo próprio para a correção. Podes seguir a ordem ou escolher a matéria de que precisas.</p><a href="#dossie" data-private>O meu dossiê →</a></div><section class="provas-porta" aria-labelledby="provas-porta-t"><div><p class="eyebrow">Provas em cartões</p><h2 id="provas-porta-t">Os exames nacionais, grupo a grupo</h2><p>A Prova 639 de 2026, 1.ª fase, em três lições de cartões: o texto da prova, cada item desmontado em exercícios no ecrã e a resposta completa no caderno, com a grelha oficial à vista.</p></div><a href="provas/">Abrir as provas em cartões →</a></section><form class="filters" id="filters"><label>Procurar matéria ou competência<input id="search" type="search" placeholder="Camões, inferência, gramática…" value="'+e(filters.text)+'"></label><label>Escolher um conjunto<select id="group"><option value="">Todos os conjuntos</option>'+['10.º ano','11.º ano','12.º ano','Competências'].map(g=>'<option'+(filters.group===g?' selected':'')+'>'+g+'</option>').join('')+'</select></label></form><p class="small" id="count" role="status"></p><div id="catalogue"></div>';app.querySelector('#filters').addEventListener('submit',ev=>ev.preventDefault());app.querySelector('#search').addEventListener('input',ev=>{filters.text=ev.target.value;cards();});app.querySelector('#group').addEventListener('change',ev=>{filters.group=ev.target.value;cards();});cards();}
function normalize(v){return v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function cards(){const query=normalize(filters.text),sessions=data.sessions.filter(s=>(!filters.group||s.group===filters.group)&&normalize([s.title,s.focus,s.module,...s.tags].join(' ')).includes(query));document.getElementById('count').textContent=sessions.length+' de '+data.sessions.length+' sessões';document.getElementById('catalogue').innerHTML=sessions.length?['10.º ano','11.º ano','12.º ano','Competências'].map((g,i)=>{const rows=sessions.filter(s=>s.group===g);return rows.length?'<section class="catalogue-group" data-grupo="'+i+'"><h2>'+g+'</h2><div class="session-grid">'+rows.map(s=>'<article class="session-card"><span class="number">'+String(s.order).padStart(2,'0')+' · '+e(s.module)+'</span><h3>'+e(s.title)+'</h3><p>'+e(s.focus)+'</p><p class="card-meta">45 min · '+s.writing.minutes+' min de escrita</p><a href="#'+s.id+'/aquecer">Abrir sessão →</a></article>').join('')+'</div></section>':'';}).join(''):'<p class="empty">Não encontrei sessões com essa pesquisa. Experimenta o nome de um autor ou uma competência.</p>';}
function coverage(){document.title='Programa e fontes · Preparação de exame';app.innerHTML='<article class="coverage"><p class="eyebrow">Mapa de estudo</p><h1>O programa.<br>As ligações.</h1><p>Este percurso trabalha leitura, educação literária, gramática e escrita, recorrendo aos materiais dos nove módulos. Escolhe as obras e os textos que estudaste: as alternativas curriculares não são tarefas obrigatórias adicionais.</p><p class="callout">Referencial de partida: Informação-Prova 639 de 2026 e Aprendizagens Essenciais indicadas pela DGE. Consulta as orientações da época em que vais realizar o exame. Estas sessões são treino autoral; não reproduzem uma prova nem constituem critérios oficiais de classificação.</p><section><h2>Fontes oficiais e materiais de apoio</h2>'+list(data.sources.map(s=>s.label))+'<div class="source-links">'+data.sources.map(link).join('')+'</div></section><section><h2>Mapa das sessões</h2><table><thead><tr><th>Sessão</th><th>Foco</th><th>Apoio</th></tr></thead><tbody>'+data.sessions.map(s=>'<tr><td><a href="#'+s.id+'/aquecer">'+String(s.order).padStart(2,'0')+' · '+e(s.title)+'</a></td><td>'+e(s.focus)+'</td><td>'+link({label:s.module,url:s.source.url})+'</td></tr>').join('')+'</tbody></table></section><section><h2>Como cabe em 45 minutos?</h2><p>Aquecer (5 min), ler e planear (8 min), escrever (10–20 min), corrigir (7–17 min) e fechar (5 min). A soma é sempre 45. O relógio não avança fases nem revela correções automaticamente.</p><p>A escrita extensa pode ser retomada no estudo autónomo. O dossiê permite conservar a primeira versão, a revisão e as indicações do docente.</p></section></article>';}
async function dossier(token){document.title='O meu dossiê · Português';if(projected){app.innerHTML='<h1>O dossiê fica no teu dispositivo.</h1><p>As fotografias e as notas pessoais não aparecem nesta projeção.</p><a href="#inicio">Voltar às sessões →</a>';return;}
 app.innerHTML='<div class="dossier-heading"><p class="eyebrow">O meu percurso</p><h1>Primeira versão.<br>Nova leitura.</h1><p>Guarda enunciados, respostas, correções e fotografias. Exporta uma cópia HTML para estudar fora do site, imprimir ou recuperar o dossiê noutro dispositivo.</p><p class="small">Máximo de 64 MiB de dados. O ficheiro exportado pode ser maior, por incluir as fotografias. Guardar no navegador não substitui a tua cópia exportada.</p><div class="dossier-actions"><button type="button" class="primary" id="export">Exportar dossiê</button><button type="button" id="import">Recuperar dossiê</button><input type="file" id="import-file" accept=".html,text/html" hidden><a class="button" href="#inicio">Escolher uma sessão</a></div></div><div id="entries"><p>A abrir os registos…</p></div>';
 app.querySelector('#export').addEventListener('click',async ev=>{const b=ev.currentTarget;b.disabled=true;try{await flush();const blob=await D.exportHTML();download(blob,'portugues-dossie-'+new Date().toISOString().slice(0,10)+'.html');message('Cópia preparada. Guarda o ficheiro HTML para estudar e recuperar o dossiê.');}catch(err){error(err);}finally{b.disabled=false;}});
 app.querySelector('#import').addEventListener('click',()=>app.querySelector('#import-file').click());app.querySelector('#import-file').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{const n=await D.importHTML(file);message(n+' registo(s) recuperado(s). Os registos mais recentes foram conservados.');await renderEntries(token);}catch(err){error(err);}finally{ev.target.value='';}});await renderEntries(token);}
async function renderEntries(token){const rows=await D.listEntries();if(token!==viewToken)return;revoke();const holder=document.getElementById('entries');if(!holder)return;holder.innerHTML=rows.length?rows.map(r=>'<article class="dossier-entry"><p class="eyebrow">'+e(new Date(r.updatedAt).toLocaleDateString('pt-PT'))+' · '+(r.photos||[]).length+' fotografia(s)</p><h2>'+e(r.title)+'</h2><a href="#'+e(r.sessionId)+'/fechar">Retomar sessão e editar →</a><details class="entry-details"><summary>Enunciado e proposta de correção guardados</summary><p>'+e(r.session.writing&&r.session.writing.prompt)+'</p>'+list(r.session.writing&&r.session.writing.criteria)+'<blockquote class="model">'+e(r.session.correction&&r.session.correction.model)+'</blockquote></details>'+(r.notes?'<h3>Notas</h3><p>'+e(r.notes)+'</p>':'')+(r.revisedText?'<h3>Versão revista</h3><p>'+e(r.revisedText)+'</p>':'')+'<div class="photos">'+(r.photos||[]).map(p=>photoCard(p,r.sessionId,false)).join('')+'</div><button type="button" class="text-button danger" data-delete="'+e(r.sessionId)+'">Eliminar este registo</button></article>').join(''):'<p class="empty">O dossiê começa na primeira sessão que guardares. Podes juntar as fotografias na fase «Fechar».</p>';holder.querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Eliminar este registo e as fotografias deste dispositivo? Exporta uma cópia se quiseres conservá-los.'))return;try{await D.deleteEntry(b.dataset.delete);await renderEntries(token);}catch(err){error(err);}}));}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}
async function route(){const token=++viewToken;try{await flush();if(token!==viewToken)return;leaveClock();delete document.body.dataset.fase;revoke();session=null;entry=null;revealed=false;const parts=location.hash.slice(1).split('/');if(parts[0]==='dossie'){await dossier(token);return;}if(parts[0]==='cobertura'){coverage();return;}const s=data.sessions.find(x=>x.id===parts[0]);if(!s){catalogue();return;}session=s;phase=Math.max(0,phaseKeys.indexOf(parts[1]));try{entry=projected?blank(s):(await D.getEntry(s.id)||blank(s));}catch(err){entry=blank(s);error(err);}if(token!==viewToken)return;renderSession();window.scrollTo({top:0,behavior:'auto'});}catch(err){error(err);}}
const dataURL=new URL('sessoes.json',asset);dataURL.search=new URL(asset).search;fetch(dataURL).then(r=>{if(!r.ok)throw Error('Não foi possível carregar as sessões. Recarrega a página.');return r.json();}).then(value=>{data=value;if(!Array.isArray(data.sessions)||!data.sessions.length)throw Error('As sessões não estão disponíveis.');window.addEventListener('hashchange',route);window.addEventListener('pagehide',()=>{if(saveTimeout)queueSave();});route();}).catch(err=>{app.innerHTML='<p class="empty">'+e(err.message)+' <a href="'+e(root.href)+'">Voltar a Português</a>.</p>';});
}());

