/* Textos compostos como no exame (27/10/2026): versos e estrofes, parágrafos numerados, falas de teatro, notas numeradas e crédito. Marcação dos dados: {termo|glosa} e _itálico_. */
function inline(t,notes){let h=e(t).replace(/_([^_]+)_/g,'<i>$1</i>');if(notes)h=h.replace(/\{([^|{}]+)\|([^{}]+)\}/g,(m,termo,glosa)=>{notes.push([termo,glosa]);return '<span class="glosa">'+termo+'<sup>'+notes.length+'</sup></span>';});return h;}
function fala(h){h=h.replace(/\(([^()]*)\)/g,'<span class="dida">($1)</span>');return h.replace(/^([A-ZÁÉÍÓÚÂÊÔÃÕÇ]{3,})((?:,[^:<]{1,60})?):\s*/,(m,quem,como)=>'<span class="fala-quem">'+quem+'</span>'+(como?'<span class="fala-como">'+como+'</span>':'')+': ');}
function passage(p){const notes=[];let corpo='',n=0;
 if(p.form==='verso')corpo='<div class="pass-verso">'+p.stanzas.map(st=>st.length===1&&st[0]==='[…]'?'<p class="pass-omissao"><span aria-hidden="true">[…]</span><span class="of-so-leitor">Versos omitidos.</span></p>':'<p class="estrofe">'+st.map(l=>{n++;return '<span class="vl">'+(n%5===0?'<span class="vn" aria-hidden="true">'+n+'</span>':'')+inline(l,notes)+'</span>';}).join('')+'</p>').join('')+'</div>';
 else corpo='<div class="pass-prosa'+(p.form==='cena'?' pass-cena':'')+'">'+p.paragraphs.map(q=>{const h=inline(q.text,notes);return '<p class="par">'+(q.n?'<span class="par-n">['+e(q.n)+']</span> ':'')+(p.form==='cena'?fala(h):h)+'</p>';}).join('')+'</div>';
 return '<article class="passagem" data-forma="'+e(p.form)+'"><header class="pass-cab">'+(p.label?'<span class="pass-letra">Texto '+e(p.label)+'</span>':'')+'<h4 class="pass-nome">'+inline(p.head)+'</h4></header>'+corpo+(notes.length?'<ol class="notas" aria-label="Vocabulário">'+notes.map(x=>'<li><span class="nota-t">'+x[0]+'</span> '+x[1]+'</li>').join('')+'</ol>':'')+'<p class="pass-credito">'+inline(p.credit)+'</p>'+(p.note?'<p class="pass-nota">'+e(p.note)+(p.link?' '+link({label:'Abrir a lição ↗',url:p.link}):'')+'</p>':'')+'</article>';}
/* 29/10/2026: no aquecimento, o texto de apoio aparece sem as notas de vocabulário; várias perguntas de aquecimento perguntam o sentido de uma palavra pelo contexto, e a nota dava a resposta. As notas voltam na fase Ler. */
const semGlosa=t=>String(t).replace(/\{([^|{}]+)\|[^{}]+\}/g,'$1');
function passageSemNotas(p){return passage(Object.assign({},p,Array.isArray(p.stanzas)?{stanzas:p.stanzas.map(st=>st.map(semGlosa))}:{},Array.isArray(p.paragraphs)?{paragraphs:p.paragraphs.map(q=>Object.assign({},q,{text:semGlosa(q.text)}))}:{}));}
function source(s,aquecer){const ps=Array.isArray(s.source.passages)?s.source.passages:null;return '<section class="source'+(ps?' source-textos':'')+'"><h3>'+f(s.source.title)+'</h3><p class="context">'+e(s.source.context)+'</p>'+(ps?'<div class="passagens">'+ps.map(aquecer?passageSemNotas:passage).join('')+'</div>'+(aquecer?'<p class="small">As notas de vocabulário aparecem na fase Ler.</p>':''):s.source.excerpt?'<blockquote>'+e(s.source.excerpt)+'</blockquote>':'')+'<cite>'+e(s.source.author)+'</cite><p class="note">'+e(s.source.note)+'</p><div class="source-links">'+(s.source.original?'':link({label:'Abrir a leitura de apoio ↗',url:s.source.url}))+(s.resources||[]).map(link).join('')+'</div></section>';}
function question(q){const selected=entry&&entry.answers[q.id],answered=!!selected&&Number.isInteger(selected.choice)&&selected.choice>=0&&selected.choice<q.options.length;
 return '<section class="question" data-question="'+e(q.id)+'"><h3>'+f(q.q)+'</h3><div class="choices">'+random(q.options.map((text,index)=>({text,index}))).map(o=>'<button type="button" class="choice'+(answered&&o.index===q.answer?' correct':answered&&o.index===selected.choice?' incorrect':'')+'" data-choice="'+o.index+'"'+(answered?' disabled':'')+'>'+f(o.text)+'</button>').join('')+'</div>'+(answered?'<p class="feedback"><b>'+(selected.choice===q.answer?'Certo.':'Revê esta escolha.')+'</b> '+f(q.feedback)+'</p>':'')+'</section>';}
function notes(){if(projected)return '';return '<section data-private><label class="field-label" for="notes">O que preciso de rever?</label><textarea id="notes" data-note="notes" maxlength="20000" placeholder="Regista uma dúvida, uma descoberta ou uma indicação do docente.">'+e(entry.notes)+'</textarea><label class="field-label" for="revised">A minha versão revista · opcional</label><textarea id="revised" data-note="revisedText" maxlength="60000" placeholder="Podes escrever aqui a revisão ou fotografar a versão que fizeste no papel.">'+e(entry.revisedText)+'</textarea><div class="save-row"><button type="button" data-action="save">Guardar no dossiê</button><span class="save-status" data-save-status>As notas e fotografias ficam neste dispositivo.</span></div></section>';}
function checklist(){return '<div class="checklist">'+session.writing.criteria.map((text,i)=>'<label><input type="checkbox" data-check="'+i+'"'+(entry.checklist['c'+i]?' checked':'')+'>'+f(text)+'</label>').join('')+'</div>';}
function corrections(){const c=session.correction;return '<p class="small">Proposta comentada para estudar e discutir. Outras respostas fundamentadas podem ser válidas.</p><h3>'+e(c.kind||'Orientação de correção')+'</h3><blockquote class="model">'+f(c.model)+'</blockquote><ol class="correction-steps">'+c.steps.map(x=>'<li><b>'+e(x.label)+'</b>'+e(x.detail)+'</li>').join('')+'</ol><h3>O que evitar</h3>'+list(c.pitfalls)+'<h3>Experimenta corrigir</h3>'+question(c.check)+'<h3>Revê a tua resposta</h3>'+checklist();}
function videoLesson(){const v=session.video;return '<h2 class="phase-title">Vê, pausa, põe à prova.</h2><p>'+e(v.intro)+'</p><p class="small">'+e(v.title)+' · '+e(v.author)+' · '+link({label:'Abrir vídeo completo ↗',url:v.url})+'</p><div class="video-clips">'+v.clips.map((c,i)=>'<section class="video-clip"><h3>'+e(c.label)+'</h3><p>'+e(c.observe)+'</p>'+(v.embeddable===false?'<p>'+link({label:'Abrir este trecho no YouTube ↗',url:v.url+'&t='+c.start+'s'})+'</p>':'<div class="video-player" data-video-slot="'+i+'"><button type="button" data-video="'+i+'">Carregar este trecho</button></div>')+'</section>').join('')+'</div>'+(v.playbackNote?'<p class="small">'+e(v.playbackNote)+'</p>':'')+'<details class="video-fallback"'+(v.embeddable===false?' open':'')+'><summary>Sem vídeo? Trabalhar a mesma ideia em texto</summary><p>'+e(v.fallback)+'</p></details><p class="small">'+e(v.note)+'</p><h3>Compreender e aplicar</h3>'+v.questions.map(question).join('')+'<h3>Dois casos para experimentar</h3>'+source(session);}
function phaseContent(){if(phase===0)return '<h2 class="phase-title">Ativa o que sabes.</h2><p>Duas perguntas para começar. Responde e lê a explicação, mesmo quando acertas. Podes consultar o texto antes de responder.</p><details><summary>Consultar leitura de apoio</summary>'+source(session,true)+'</details><div id="questions">'+currentQuestions().map(question).join('')+'</div><button type="button" class="text-button" data-action="another">Outro aquecimento</button>';
 if(phase===1&&session.video)return videoLesson();
 if(phase===1)return '<h2 class="phase-title">Lê com uma pergunta em mente.</h2><p>'+f(session.focus)+'</p>'+source(session)+'<p class="callout">Sublinha no texto duas pistas que poderão sustentar a tua resposta. Na projeção, abre a leitura de apoio quando precisares do recorte completo.</p>'+alternatives();
 if(phase===2)return '<h2 class="phase-title">'+e(session.writing.title)+'</h2><p class="writing-target">'+session.writing.minutes+' minutos · '+e(session.writing.target)+'</p><p class="writing-task">'+f(session.writing.prompt)+'</p>'+list(session.writing.instructions)+'<h3>Antes de entregar</h3>'+list(session.writing.criteria)+'<p class="callout">Responde no caderno ou em papel. Identifica a sessão e deixa espaço para a revisão.</p>';
 if(phase===3)return '<h2 class="phase-title">Da resposta à revisão.</h2><p>Compara a tua resposta com os critérios. Identifica primeiro o que funciona e depois o que precisas de alterar.</p><button type="button" class="primary" data-action="reveal" aria-expanded="'+revealed+'" aria-controls="correction">'+(revealed?'Recolher proposta de correção':'Mostrar proposta de correção')+'</button><div id="correction"'+(revealed?'':' hidden')+'>'+(revealed?corrections():'')+'</div>'+(!projected?notes():'');
 return '<h2 class="phase-title">Leva uma melhoria contigo.</h2><p class="writing-task">'+e(session.exit)+'</p>'+checklist()+(!projected?notes()+'<h3>Regista a resposta que fizeste no papel</h3><p class="small">Junta até quatro fotografias legíveis a esta sessão. JPEG, PNG ou WebP, até 8 MiB por imagem. São guardadas com o enunciado e a correção, neste dispositivo.</p><button type="button" data-action="photos">Adicionar fotografias</button><input type="file" id="photo-input" accept="image/jpeg,image/png,image/webp" multiple hidden><div id="session-photos" class="photos"></div>':'<p class="callout">No teu dispositivo, abre o dossiê desta sessão para guardar as fotografias e a versão revista.</p>')+'<div class="dossier-actions"><a class="button primary" href="#inicio">Voltar às sessões</a>'+(!projected?'<a class="button" href="#dossie">Abrir o meu dossiê</a>':'')+'</div>';}
function alternatives(){if(!session.alternatives||!session.alternatives.length)return '';return '<details class="alternatives"><summary>Outra obra no teu percurso?</summary><p class="small">Escolhe a obra que estudaste. A tarefa mantém a competência, com as adaptações indicadas.</p><ul>'+session.alternatives.map(x=>'<li><b>'+e(x.label)+'</b><p>'+e(x.instruction)+'</p>'+link({label:'Referência e leitura ↗',url:x.url})+'</li>').join('')+'</ul></details>';}
function renderSession(){document.title=session.title+' · Preparação de exame';document.body.dataset.fase=phaseKeys[phase];const index=data.sessions.indexOf(session),previous=data.sessions[index-1],next=data.sessions[index+1];
 app.innerHTML='<div class="session-heading"><p class="eyebrow">Sessão '+String(session.order).padStart(2,'0')+' · '+e(session.group)+' · 45 minutos</p><h1>'+e(session.title)+'</h1><p>'+f(session.focus)+'</p></div><nav class="session-nav" aria-label="Percurso sugerido">'+(previous?'<a href="#'+previous.id+'/aquecer">← '+e(previous.title)+'</a>':'<a href="#inicio">← Todas as sessões</a>')+(next?'<a href="#'+next.id+'/aquecer">'+e(next.title)+' →</a>':'<a href="#inicio">Todas as sessões →</a>')+'</nav><ol class="phase-nav" aria-label="Fases da sessão">'+phaseNames.map((original,i)=>{const name=phaseLabel(i);return '<li><a data-fase="'+phaseKeys[i]+'" href="#'+session.id+'/'+phaseKeys[i]+'"'+(i===phase?' aria-current="step"':'')+'><span class="fase-n" aria-hidden="true">0'+(i+1)+'</span>'+e(name)+'<small>'+duration(session,i)/60+' min</small></a></li>';}).join('')+'</ol><div class="session-layout"><section class="phase-content">'+phaseContent()+'<nav class="phase-actions" aria-label="Avançar na sessão">'+(phase?'<a class="button" href="#'+session.id+'/'+phaseKeys[phase-1]+'">← '+phaseLabel(phase-1)+'</a>':'<span></span>')+(phase<4?'<a class="button primary" href="#'+session.id+'/'+phaseKeys[phase+1]+'">'+phaseLabel(phase+1)+' →</a>':'')+'</nav></section><aside class="session-tools" aria-label="Relógio e materiais"><div class="session-relogio" id="relogio-fase"></div><div class="tool-links"><button type="button" data-action="print">Imprimir enunciado</button><button type="button" data-action="print-correction">Imprimir correção</button>'+(!projected?'<a href="#dossie">O meu dossiê →</a>':'')+'<a href="#cobertura">Programa e fontes →</a></div></aside></div>';
 bindSession();mountClock();if(phase===4&&!projected)renderPhotos().catch(error);}
/* Relógio do aluno (27/10/2026): duração escolhida até ao tempo da fase; duas pausas; depois, parar recomeça.
   29/10/2026: um relógio por sessão e fase, guardado em memória. Voltar a desenhar a fase (proposta de correção, outro aquecimento)
   volta a pôr o mesmo relógio, mesmo sem armazenamento; sair da fase com o relógio a contar conta como pausa, como no laboratório. */
function mountClock(){const slot=document.getElementById('relogio-fase');if(!slot||!window.EPIRelogio)return;const key=session.id+'-'+phaseKeys[phase];
 if(!clocks[key]){const host=document.createElement('div');clocks[key]={box:host,api:EPIRelogio.criar(host,{max:duration(session,phase)/60,passo:1,rotulo:'Tempo para '+(session.video&&phase===1?'ver e aplicar':phaseNames[phase].toLowerCase()),chave:'pt-exame-relogio-'+key})};}
 slot.replaceChildren(clocks[key].box);clock=clocks[key].api;clock.atualizar();}
function leaveClock(){if(!clock)return;const c=clock;clock=null;if(!c.estado().corre)return;c.pausar();const s=c.estado();message(s.iniciado?'Relógio da fase em pausa (pausa '+s.pausasUsadas+' de 2).':'Usaste as duas pausas: o relógio da fase voltou ao início.');}
function bindSession(){bindQuestionButtons();
 app.querySelectorAll('[data-video]').forEach(b=>b.addEventListener('click',()=>{const c=session.video&&session.video.clips[Number(b.dataset.video)];if(!c||!/^[A-Za-z0-9_-]{11}$/.test(c.id)||!Number.isInteger(c.start)||!Number.isInteger(c.end)||c.start<0||c.end<=c.start)return;const f=document.createElement('iframe');f.src='https://www.youtube-nocookie.com/embed/'+c.id+'?start='+c.start+'&end='+c.end+'&rel=0';f.title=c.label+' · '+session.video.author;f.allow='encrypted-media; picture-in-picture; fullscreen';f.allowFullscreen=true;f.referrerPolicy='strict-origin-when-cross-origin';b.parentElement.replaceChildren(f);}));
 app.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action).catch(error)));
 app.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>{entry[el.dataset.note]=el.value;scheduleSave();}));
 app.querySelectorAll('[data-check]').forEach(el=>el.addEventListener('change',()=>{entry.checklist['c'+el.dataset.check]=el.checked;queueSave();}));const file=document.getElementById('photo-input');if(file)file.addEventListener('change',async()=>{const id=session.id,snapshot=structuredClone(session),token=viewToken,files=Array.from(file.files);try{await flush();const saved=await D.addPhotos(id,files,snapshot);if(token===viewToken){entry=saved;await renderPhotos();}message('Fotografias guardadas com esta sessão.');}catch(err){error(err);}finally{file.value='';}});}
